namespace bgiplayer {
std::vector<std::string> ArchiveSet::enumerate_files(
    std::string_view pattern, bool recursive, std::size_t limit) const {
    const std::string normalized = host_files::separators(pattern);
    const std::size_t slash = normalized.find_last_of('/');
    const std::string directory =
        slash == std::string::npos ? std::string() : normalized.substr(0, slash);
    const std::string file_pattern =
        slash == std::string::npos ? normalized : normalized.substr(slash + 1);
    const std::filesystem::path root =
        directory.empty() ? game_root_ : game_root_ / directory;
    std::vector<std::string> names;
    std::error_code error;
    if (!host_files::is_directory(root, error)) {
        return names;
    }
    for (const auto& entry : host_files::entries(root, recursive, error)) {
        if (limit != 0 && names.size() >= limit) break;
        if (!entry.regular) continue;
        if (matches_windows_pattern(file_pattern, entry.path.filename().string())) {
            names.push_back(recursive ? entry.path.lexically_relative(root).generic_string()
                                      : entry.path.filename().string());
        }
    }
    std::sort(names.begin(), names.end());
    return names;
}
}  // namespace bgiplayer
